function determineProtocol(inputData) {
  let protocol;

  if (inputData.protocol === undefined) { // Check if protocol is already provided in inputData
    if (isValidIPv6Address(inputData.sourceIP) && isValidIPv6Address(inputData.destinationIP)) { // Check if both source and destination are IPv6 addresses
      protocol = "IPv6";
    } else if (inputData.port === 80) { // Check if HTTP is used for web traffic (HTTP uses port 80 by default)
      protocol = "HTTP";
    } else if (typeof inputData.payload !== 'string' || inputData.payload.length === 0) { // Check if UDP is used for datagrams without payload
      protocol = "UDP";
    }
  }

  return protocol;
}
// Helper function to check if an IPv6 address is valid
function isValidIPv6Address(ipAddress) {
  const regex = /^([0-9a-f:]{1,4})(:[0-9a-f]{1,4}){7}$/i;
  return regex.test(ipAddress);
}
// Sample usage:
