2. In your `Startup.cs` file, configure the JWT authentication middleware within the `ConfigureServices()` method:

```csharp
services.AddAuthentication(options =>
{
    options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
})
.AddJwtBearer(options =>
{
    // Configure JWT Bearer options here
});
```

3. Next, create or modify an existing middleware component that extracts the username from the JWT token. This can be done using a custom `DelegateAuthenticationMiddleware` as shown below:

```csharp
public class CustomJwtDelegateAuthenticationMiddleware
{
    private readonly RequestDelegate _next;

    public CustomJwtDelegateAuthenticationMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context, IConfiguration configuration)
    {
        var authHeader = context.Request.Headers["Authorization"].FirstOrDefault()?.Split(" ").Last();
        if (!string.IsNullOrEmpty(authHeader) && authHeader.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase))
        {
            var handler = new JwtSecurityTokenHandler();
            var jwtToken = handler.ReadJwtToken(authHeader);
            var identity = new ClaimsIdentity(jwtToken.Claims, jwtToken.Principal.Identity);
            context.User = new ClaimsPrincipal(identity);
        }

        await _next(context);
    }
}
```

