 To create a simple toast notification using React and the useContextHook, follow these steps:

First, let's create a custom context provider for managing the toast messages and showing notifications.

1. Create a new file called `ToastContext.js`:

```javascript
import { createContext, useState } from 'react';

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = useState([]);

  const addToast = (message) => {
    setToasts((prevToasts) => [...prevToasts, message]);
    setTimeout(() => setToasts(prevToasts.filter((_, i) => i !== prevToasts.length - 1)), 3000); // Auto-hide after 3 seconds
  };

  return (
    <ToastContext.Provider value={{ addToast }}>
      {children}
      <div id="toast-container" style={{ position: 'fixed', bottom: '0', right: '0', padding: '1rem', zIndex: '9999' }}>
        {toasts.map((toast, index) => (
          <div key={index} className="toast">{toast}</div>
        ))}
      </div>
    </ToastContext.Provider>
  );
};
```

2. Wrap your application in the `ToastProvider` component:

```javascript
// Index.js or App.js
import React from 'react';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import ToastProvider from './ToastContext';
import HomePage from './HomePage';
import AboutPage from './AboutPage';

function App() {
  return (
    <ToastProvider>
      <Router>
        <Switch>
          <Route exact path="/">
            <HomePage />
          </Route>
          <Route path="/about">
            <AboutPage />
          </Route>
        </Switch>
      </Router>
    </ToastProvider>
  );
}

export default App;
```

