async function checkCameraAndMicrophoneStatus() {
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
    return { cameraAvailable: !!stream.videoTrack, microphoneAvailable: !!stream.audioTracks[0] };
  } catch (error) {
    console.error('Error accessing media devices.', error);
    return { cameraAvailable: false, microphoneAvailable: false };
  }
}
