```javascript
function openCamera(onSuccess, onError) {
  navigator.mediaDevices.getUserMedia({ video: true })
    .then((stream) => {
      if (onSuccess) onSuccess(stream);
    })
    .catch((error) => {
      if (onError) onError(error);
    });
}
```

3. `closeCamera`: This method closes the camera stream when called.

